const rooms=new Map();
const DATA_DIR=process.env.DATA_DIR||path.join(__dirname,'data');
const ACCOUNTS_FILE=path.join(DATA_DIR,'accounts.json');
fs.mkdirSync(DATA_DIR,{recursive:true});
let accounts={};
try{accounts=JSON.parse(fs.readFileSync(ACCOUNTS_FILE,'utf8'))||{}}catch{accounts={}}
// Normalize usernames while preserving valid persisted login tokens across a process restart.
accounts=Object.fromEntries(Object.entries(accounts).map(([u,a])=>[u.toLowerCase(),a]));
function saveAccounts(){fs.writeFileSync(ACCOUNTS_FILE,JSON.stringify(accounts,null,2))}
function cleanName(s){return String(s||'').trim().slice(0,18)}
function validUser(s){return /^[A-Za-z0-9_]{3,18}$/.test(String(s||''))}
function hashPassword(p,salt){return crypto.scryptSync(String(p),salt,64).toString('hex')}
function makeToken(){return crypto.randomBytes(32).toString('hex')}
function issueToken(username){const t=makeToken();accounts[username].token=t;accounts[username].tokenIssued=Date.now();saveAccounts();return t}
function accountFromToken(token){if(!token)return null;for(const [u,a] of Object.entries(accounts))if(a.token===token)return [u,a];return null}
const activeSockets=new Map();
saveAccounts();
function sendJson(res,status,obj){const body=JSON.stringify(obj);res.writeHead(status,{'Content-Type':'application/json','Cache-Control':'no-store'});res.end(body)}
function readBody(req){return new Promise(resolve=>{let b='';req.on('data',c=>{b+=c;if(b.length>10000)req.destroy()});req.on('end',()=>{try{resolve(JSON.parse(b||'{}'))}catch{resolve({})}})})}
// Daily quest helpers. These are required by account registration/login and WebSocket hello.
const DAILY_QUESTS=[
 {key:'dailyPlay',name:'Play a game',stars:1},
 {key:'friendly',name:'Play with another player',stars:1},
 {key:'correctStreak',name:'Get 3 correct answers',stars:1},
 {key:'correctToday',name:'Get 5 correct answers',stars:2},
 {key:'dailyWin',name:'Win a game',stars:2},
 {key:'winStreak',name:'Win 3 games in a row',stars:3},
 {key:'pointsGame',name:'Reach 5 points in a game',stars:1}
];
function ensureDaily(a){
 const today=new Date().toISOString().slice(0,10);
 if(!a.daily||typeof a.daily!=='object')a.daily={};
 if(a.daily.date!==today){const previous=a.daily;a.daily={date:today,played:false,friendly:false,correctStreak:previous.correctStreak||0,correctToday:0,wins:0,winStreak:previous.winStreak||0,pointsThisGame:0,completed:{}};}
 if(!a.daily.completed||typeof a.daily.completed!=='object')a.daily.completed={};
 for(const k of ['played','friendly','correctStreak','correctToday','wins','winStreak','pointsThisGame'])if(typeof a.daily[k]!=='number'&&typeof a.daily[k]!=='boolean')a.daily[k]=0;
 return a.daily;
}
function addStars(a,n){a.stars=Math.max(0,(Number(a.stars)||0)+n);saveAccounts();return a.stars}
function completeQuest(a,key){const d=ensureDaily(a),q=DAILY_QUESTS.find(x=>x.key===key);if(!q||d.completed[key])return false;d.completed[key]=true;addStars(a,q.stars);return true}
function questView(a){const d=ensureDaily(a);return DAILY_QUESTS.map(q=>({key:q.key,name:q.name,stars:q.stars,done:!!d.completed[q.key]}))}
